def transform(grid):
    g=[row[:] for row in grid]
    p3=p2=None
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v==3: p3=(r,c)
            if v==2: p2=(r,c)
    r=(p3[0]+p2[0])//2; c=(p3[1]+p2[1])//2
    g[r][c]=1
    return g

def transform(grid):
    g=[row[:] for row in grid]
    rs=[]; cs=[]
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v!=0: rs.append(r); cs.append(c)
    r=(min(rs)+max(rs))//2; c=(min(cs)+max(cs))//2
    g[r][c]=1
    return g

def transform(grid):
    g=[row[:] for row in grid]
    p3=p2=None
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v==3: p3=(r,c)
            if v==2: p2=(r,c)
    r=-(-(p3[0]+p2[0])//2); c=-(-(p3[1]+p2[1])//2)
    g[r][c]=1
    return g
